:root {
  --bg: #f4f5f7;
  --card: #ffffff;
  --border: #e2e5ea;
  --text: #1f2430;
  --muted: #6b7280;
  --accent: #2563eb;
  --danger: #dc2626;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

#app {
  max-width: 760px;
  margin: 0 auto;
  padding: 24px 16px 64px;
}

.app-header h1 { margin: 8px 0 20px; font-size: 1.8rem; }

.add-form, .controls, .list-region { margin-bottom: 20px; }

.add-form form {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 16px;
  display: grid;
  gap: 12px;
}

.field { display: grid; gap: 4px; }
.field label { font-size: 0.8rem; color: var(--muted); }

input[type="text"], input[type="search"] {
  width: 100%;
  padding: 9px 11px;
  border: 1px solid var(--border);
  border-radius: 7px;
  font-size: 0.95rem;
  background: #fff;
  color: var(--text);
}
input:focus { outline: 2px solid var(--accent); outline-offset: 0; }

.form-actions { display: flex; gap: 8px; }

button {
  padding: 9px 16px;
  border: none;
  border-radius: 7px;
  background: var(--accent);
  color: #fff;
  font-size: 0.9rem;
  cursor: pointer;
}
button.secondary { background: #e5e7eb; color: var(--text); }
button.link { background: none; color: var(--accent); padding: 2px 6px; }
button.link.danger { color: var(--danger); }

.error { color: var(--danger); margin: 0; font-size: 0.85rem; min-height: 1em; }

.controls { display: grid; gap: 10px; }
.tag-filter { display: flex; flex-wrap: wrap; gap: 6px; }
.tag-chip {
  border: 1px solid var(--border);
  background: #fff;
  color: var(--muted);
  border-radius: 999px;
  padding: 3px 12px;
  font-size: 0.8rem;
  cursor: pointer;
}
.tag-chip.active { background: var(--accent); color: #fff; border-color: var(--accent); }

.bookmark-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }

.bookmark {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 12px 14px;
  display: grid;
  grid-template-columns: 32px 1fr auto;
  gap: 12px;
  align-items: start;
}

.bookmark .favicon {
  width: 28px; height: 28px; border-radius: 6px;
  object-fit: cover; background: #eef1f5;
}

.bookmark .body { min-width: 0; }
.bookmark .title {
  font-weight: 600; margin: 0 0 2px;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.bookmark .title a { color: var(--text); text-decoration: none; }
.bookmark .title a:hover { color: var(--accent); }
.bookmark .addr {
  color: var(--muted); font-size: 0.8rem; margin: 0 0 4px;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.bookmark .desc {
  font-size: 0.88rem; margin: 0 0 6px; color: #374151;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
}
.bookmark .tags { display: flex; flex-wrap: wrap; gap: 5px; }
.bookmark .tags .tag {
  font-size: 0.72rem; background: #eef2ff; color: #3730a3;
  border-radius: 999px; padding: 2px 8px;
}
.bookmark .actions { display: flex; flex-direction: column; gap: 2px; align-items: flex-end; }

.empty { text-align: center; color: var(--muted); padding: 40px 0; }

